<script setup lang="ts">
import{ref}from'vue';import Taro,{useDidShow}from'@tarojs/taro';import PageShell from '@/components/PageShell.vue';import SectionCard from '@/components/SectionCard.vue';import StatePanel from '@/components/StatePanel.vue';import StatusBadge from '@/components/StatusBadge.vue';import{api}from'@/lib/api';import{errorMessage}from'@/lib/errors';import{shortDate,yuan}from'@/lib/format';import type{ConsumerOrder,PurchaseIntent}from'@/lib/types';
const orders=ref<ConsumerOrder[]>([]),intents=ref<PurchaseIntent[]>([]),loading=ref(true),error=ref('');async function load(){loading.value=true;error.value='';try{const[o,i]=await Promise.all([api.orders(),api.purchaseIntents()]);orders.value=o.data.orders;intents.value=i.data.intents.filter(v=>v.status==='proposed');}catch(e){error.value=errorMessage(e);}finally{loading.value=false;}}useDidShow(()=>{void load();});
const payment=(s:string)=>({pending:'待付款',paid:'已付款',unknown:'结果待核验',closed:'已关闭',failed:'付款失败'}[s]??s);const tone=(s:string)=>s==='paid'?'success':s==='unknown'?'warning':s==='pending'?'info':'neutral';function goBack(){void Taro.navigateBack({fail:()=>{void Taro.switchTab({url:'/pages/profile/index'});}});}
</script>
<template><PageShell title="订单与确认" subtitle="退出重登后仍可从这里恢复" compact><template #hero><button class="back" aria-label="返回" @tap="goBack">‹</button></template><StatePanel v-if="loading" title="正在恢复本人状态"/><StatePanel v-else-if="error" title="订单暂时不可用" :detail="error" tone="error"><button class="secondary-button retry" @tap="load">重新加载</button></StatePanel><template v-else><text class="heading">等待你确认</text><view v-if="intents.length" class="list"><SectionCard v-for="v in intents" :key="v.purchaseIntentId" class="order-card intent-card" @tap="Taro.navigateTo({url:`/pages/purchase/detail?id=${v.purchaseIntentId}`})"><view class="row-between"><text class="title">{{v.offerName}}</text><StatusBadge label="待确认" tone="info"/></view><text class="amount">{{yuan(v.quotedAmountMinor)}}</text><text class="meta">{{shortDate(v.plannedOn)}} · 查看购买确认</text></SectionCard></view><view v-else class="compact-empty">没有待确认意图。选择候选后，会先在这里等待你的确认。</view><text class="heading heading--orders">我的订单</text><view v-if="orders.length" class="list"><SectionCard v-for="v in orders" :key="v.orderId" class="order-card" @tap="Taro.navigateTo({url:`/pages/order/detail?id=${v.orderId}`})"><view class="row-between"><text class="title">{{v.itemName}}</text><StatusBadge :label="payment(v.paymentStatus)" :tone="tone(v.paymentStatus)"/></view><text class="amount">{{yuan(v.amountMinor)}}</text><view class="meta-row"><text class="environment">{{v.environment==='simulation'?'Simulation 本地模拟':'Sandbox 支付宝沙箱'}}</text><text class="meta">{{shortDate(v.updatedAt)}} · 查看详情</text></view></SectionCard></view><view v-else class="compact-empty">还没有订单。购买意图经你确认后才会建立订单。</view></template></PageShell></template>
<style lang="scss">@use '../../styles/tokens' as *;.back{position:absolute;right:28px;top:calc(34px + env(safe-area-inset-top));width:64px;height:64px;border-radius:50%;font-size:44px}.retry{margin-top:24px}.heading{display:block;margin:6px 6px 16px;font-size:36px;font-weight:740}.heading--orders{margin-top:36px}.list{display:grid;gap:20px}.order-card{overflow:hidden}.intent-card{background:linear-gradient(145deg,#EEF7FB,#fff);border-left:7px solid $info}.title{font-size:32px;font-weight:700;line-height:1.4}.amount,.meta,.environment{display:block}.amount{margin-top:22px;font-size:42px;font-weight:770}.meta-row{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin-top:14px}.meta{color:$text-secondary;font-size:26px}.environment{padding:7px 14px;color:$brand-deep;background:$surface-tint;border-radius:999px;font-size:24px;font-weight:650}.compact-empty{padding:22px 24px;color:$text-secondary;background:$soft-surface;border-radius:22px;font-size:27px;line-height:1.55}@media screen and (max-width:360px){.row-between{align-items:flex-start}.meta-row{align-items:flex-start;flex-direction:column}}</style>
